import math

def countDigitOne(n: int) -> int:
    n_list = list(map(int, str(n)))
    res = 0
    count_1 = 0

    for i in range(len(n_list) - 1):
        if n_list[i] == 1:
            temp_res = count(count_1, len(n_list) - i - 1)
            res += temp_res
        elif n_list[i] > 1:
            leading = n_list[i] - 1
            temp_res = count(count_1, len(n_list) - i - 1)
            res += temp_res * leading + count(count_1 + 1, len(n_list) - i - 1)

    if n_list[-1] >= 1:
        res += 1

    return res

def count(add: int, n_digit: int) -> int:
    c = 0
    for d in range(n_digit + 1):
        c += (d + add) * math.comb(n_digit, d) * pow(9, n_digit - d)
    return c
